-- MASEST products - generated by tools/build-catalog.mjs from data/catalog.seed.json. DO NOT edit by hand.
on conflict (sku) do update set
  name = excluded.name,
  group_key = excluded.group_key,
  hmis = excluded.hmis,
  mode = excluded.mode,
  hazmat = excluded.hazmat,
  taxable = excluded.taxable,
  active = excluded.active,
  sort = excluded.sort;

delete from public.products where sku not in ('cr','cr2','hcr','hcr-t16','descaler','cr-hd','cr-hd-low-foam','neutral','multiwash','lam3','purgo','alumibrite','torque','sar','watersafe60','cr60');
